out('table','''@{'''+base+text+'''display:flex;align-items:stretch} @ .table{border-collapse:collapse;table-layout:fixed;width:100%;height:100%;font:inherit} @ th,@ td{box-sizing:border-box;padding:var(--gap-sm) var(--gap);text-align:left;border-bottom:1px solid var(--n-3);overflow-wrap:anywhere;font-weight:var(--body-weight)} @ thead{background:var(--a1-7);color:var(--page)} @ thead th{font-weight:var(--name-weight)} @ tbody th{font-weight:var(--name-weight);width:30%;background:var(--n-1)} @ tbody td{background:var(--n-1)} @ .num{text-align:right;font-variant-numeric:tabular-nums} @ .pick{background:var(--a1-7);color:var(--page);font-weight:var(--name-weight)} @container(max-width:600px){@ th,@ td{padding:calc(var(--gap-sm)/2) var(--gap-sm);font-size:var(--type-14)}}''','A full-height ruled table uses a deep accent heading and calm neutral body cells. Numeric columns align right. Emphasized columns retain one continuous accent stripe; row labels may use semantic row headers without inventing a visible column heading.')
legend='''@{'''+base+text+'''display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:repeat(var(--crossrail-key-rows),minmax(0,1fr));grid-auto-flow:column;gap:calc(var(--gap-sm)*.75) calc(var(--gap)*.8);align-content:center;--crossrail-key-rows:3} @ .key{box-sizing:border-box;display:flex;align-items:center;justify-content:center;gap:var(--gap-sm);height:min(31cqh,12.8cqw);align-self:center;border:1px solid var(--n-4);border-radius:999px;padding:0 var(--gap-sm);font-size:var(--type-26);font-weight:var(--name-weight);line-height:var(--label-line);letter-spacing:var(--label-track);white-space:nowrap;color:var(--ink)} @ .key::before{content:"";width:12px;height:12px;flex:none;border-radius:50%;background:var(--a1-7)} @ .key.tone-2::before{background:var(--a2-7)} @ .key.tone-3::before{background:var(--a3-7)} @ .key.tone-4::before{background:var(--a4-7)} @ .key.tone-5::before{background:var(--n-6)} @ .key b{font-weight:var(--figure-weight);color:var(--ink)} @container(max-width:600px){@ .key{font-size:var(--type-16);gap:calc(var(--gap-sm)/2)}}'''
