out('roadmap',road,'Quiet duration lanes share a period grid and a left-hand label rail. Strong rectangular bars occupy exactly their start and exclusive end periods; fine milestone stems remain moments rather than fabricated durations.')
position='''@{'''+base+text+'''background:var(--n-1);border-left:1px solid var(--ink);border-bottom:1px solid var(--ink)} @::before{content:"";position:absolute;left:14%;right:4.5%;top:4.5%;bottom:12%;background:linear-gradient(to right,transparent calc(50% - .5px),var(--n-5) 0,var(--n-5) calc(50% + .5px),transparent 0),linear-gradient(to bottom,transparent calc(50% - .5px),var(--n-5) 0,var(--n-5) calc(50% + .5px),transparent 0)} @ .axis-x{position:absolute;left:14%;right:4.5%;bottom:var(--gap-sm);display:flex;justify-content:space-between;font-size:var(--type-18);line-height:var(--label-line)} @ .axis-y{position:absolute;left:var(--gap-sm);top:4.5%;bottom:12%;width:12%;display:flex;flex-direction:column-reverse;justify-content:space-between;font-size:var(--type-18);line-height:var(--label-line)} @ .mark{position:absolute;left:calc(14% + 81.5%*var(--x)/100);bottom:calc(12% + 83.5%*var(--y)/100);width:min(18.25cqw,23.85cqh);height:min(18.25cqw,23.85cqh);transform:translate(-50%,50%);border-radius:50%;display:flex;align-items:center;justify-content:center;box-sizing:border-box;padding:calc(var(--gap-sm)/2);background:var(--n-3);color:var(--ink);text-align:center} @ .mark.on{background:var(--a1-7);color:var(--page)} @ .mark .name{margin:0;font-size:var(--type-18);font-weight:var(--name-weight);line-height:var(--name-line)} @ .mark .seat{width:75%;height:75%;display:flex;align-items:center;justify-content:center;background:var(--n-2);color:var(--ink);font-size:var(--type-16)} @container(max-width:550px){@ .axis-x,@ .axis-y,@ .mark .name{font-size:var(--type-14)}}'''
