track='''@{'''+base+text+'''display:flex;gap:var(--gap);padding:var(--gap-sm);isolation:isolate} @::before{content:"";position:absolute;left:var(--gap-sm);right:var(--gap-sm);top:38%;border-top:1px solid var(--n-4);z-index:-1} @ .stop{position:relative;flex:1;min-width:0;display:flex;flex-direction:column;padding-top:52cqh;box-sizing:border-box} @ .stop::before{content:"";position:absolute;left:50%;top:calc(38cqh - 5px);width:10px;height:10px;border-radius:50%;background:var(--a1-7);transform:translateX(-50%)} @ .kick{position:absolute;left:0;right:0;top:calc(38cqh - min(13.6cqh,5cqw)/2);height:min(13.6cqh,5cqw);border:1px solid var(--n-4);border-radius:999px;background:var(--page);display:flex;align-items:center;justify-content:center;font-size:var(--type-26);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track)} @ .name{'''+name+'''} @ .note{'''+note+'''margin-top:var(--gap-sm)} @ .stop.on .kick{background:var(--a1-7);color:var(--page);border-color:var(--a1-7)} @.alt::before{top:49.1%} @.alt .stop::before{top:calc(49.1cqh - 5px)} @.alt .kick{top:calc(49.1cqh - min(13.6cqh,5cqw)/2)} @.alt .stop:nth-child(odd){padding-top:65cqh} @.alt .stop:nth-child(even){padding-top:0;padding-bottom:65cqh} @.col{flex-direction:column;gap:var(--gap-sm);padding-left:var(--gap-lg)} @.col::before{left:calc(var(--gap-lg)/2);right:auto;top:var(--gap-sm);bottom:var(--gap-sm);border-top:0;border-left:1px solid var(--n-4)} @.col .stop{display:grid;grid-template-columns:24% minmax(0,1fr);grid-template-rows:auto 1fr;gap:calc(var(--gap-sm)/2) var(--gap);padding:0;align-content:center} @.col .stop::before{left:calc(var(--gap-lg)/-2);top:50%;transform:translate(-50%,-50%)} @.col .kick{position:static;grid-column:1;grid-row:1/3;height:auto;min-height:42px;align-self:center;font-size:var(--type-22)} @.col .name{grid-column:2;grid-row:1} @.col .note{grid-column:2;grid-row:2;margin-top:0} @container(max-width:700px){@ .name{font-size:var(--type-20)} @ .note{font-size:var(--type-14)} @ .kick{font-size:var(--type-20)}}'''
out('timeline',track,'Outline date capsules sit on one thin continuous time axis. The alternate form places whole events above and below that axis; the vertical form gives dates a separate label column so longer event descriptions remain aligned.')
out('versus','''@{'''+base+text+'''display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--gap-lg)} @ .side{position:relative;min-width:0;display:flex;flex-direction:column;justify-content:center;padding:var(--pad);box-sizing:border-box;border-top:2px solid var(--n-4);border-bottom:1px solid var(--n-4);gap:var(--gap)} @ .side.on{border-top-color:var(--a1-7);background:var(--n-1)} @ .side>.name{'''+name+'''} @ .side>.note{'''+note+'''} @ .side>.fig{font-size:var(--type-52);font-weight:var(--figure-weight);line-height:var(--figure-line)} @ .side>.list{flex:1;min-height:0} @ .vs{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:48px;height:48px;display:flex;align-items:center;justify-content:center;border-radius:50%;background:var(--page);border:1px solid var(--n-4);font-size:var(--type-18);font-weight:var(--label-weight);z-index:2} @container(max-width:700px){@ .side{padding:var(--gap-sm);gap:var(--gap-sm)} @ .side>.name{font-size:var(--type-22)} @ .side>.note{font-size:var(--type-16)}}''','Two equal evidence panels meet across a quiet gap. Thin bounding rules and a restrained centre label establish comparison without turning the two sides into unrelated decorative cards.')
