hub='''@{'''+base+text+'''--crossrail-hub-count:4;--crossrail-hub-radius:min(40cqw,58cqh)} @::before{content:"";position:absolute;left:50%;bottom:21%;width:calc(var(--crossrail-hub-radius)*2);height:var(--crossrail-hub-radius);transform:translateX(-50%);box-sizing:border-box;border:2px solid var(--n-3);border-bottom:0;border-radius:999px 999px 0 0} @ .core{position:absolute;left:50%;bottom:4%;transform:translateX(-50%);width:36%;height:25%;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center} @ .core .name{'''+name+'''} @ .core .icon{width:50px;height:50px} @ .spoke{position:absolute;left:calc(50% + cos(var(--crossrail-spoke-angle))*var(--crossrail-hub-radius));top:calc(79% + sin(var(--crossrail-spoke-angle))*var(--crossrail-hub-radius));width:min(19cqw,26cqh);height:min(19cqw,26cqh);transform:translate(-50%,-50%);box-sizing:border-box;border-radius:50%;background:var(--a1-7);color:var(--page);display:flex;flex-direction:column;align-items:center;justify-content:center;padding:calc(var(--gap-sm)/2);text-align:center} @ .spoke .mark{position:absolute;top:calc(var(--gap-sm)/2);left:50%;transform:translateX(-50%);font-size:var(--type-14);font-weight:var(--label-weight)} @ .spoke .name{margin:0;font-size:var(--type-20);font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track)} @ .spoke .note{position:absolute;left:50%;top:calc(100% + var(--gap-sm)/2);transform:translateX(-50%);width:150%;margin:0;font-size:var(--type-14);font-weight:var(--body-weight);line-height:var(--body-line);color:var(--ink)} @container(max-width:650px){@ .spoke .name{font-size:var(--type-16)} @ .spoke .note{font-size:var(--type-12)} @ .core .name{font-size:var(--type-22)}}'''
for n in range(3,7):
 hub+=f' @:has(>.spoke:nth-child({n} of .spoke):last-child){{--crossrail-hub-count:{n}}}'
 for i in range(1,n+1):hub+=f' @:has(>.spoke:nth-child({n} of .spoke):last-child)>.spoke:nth-child({i} of .spoke){{--crossrail-spoke-angle:{-155+(130/(n-1))*(i-1)}deg}}'
out('hub',hub,'A shallow open arch places equally weighted round members around a low central label. The arch remains a quiet structural guide; member names stay inside the circles and their short notes sit immediately beneath.',{'--crossrail-hub-count':'4','--crossrail-hub-radius':'min(40cqw,58cqh)'})
out('code','''@{'''+base+'''display:flex;flex-direction:column;padding:var(--pad);border-top:2px solid var(--a1-7);border-bottom:1px solid var(--n-4);background:var(--n-1);font-family:var(--crossrail-font-code);color:var(--ink)} @>.name{margin:0 0 var(--gap);padding-bottom:var(--gap-sm);border-bottom:1px solid var(--n-4);font-family:var(--font-body);font-size:var(--type-18);font-weight:var(--label-weight);line-height:var(--label-line)} @ .lines{counter-reset:source-line;min-width:0;display:flex;flex-direction:column;justify-content:center;flex:1} @ .lines p{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font-family:var(--crossrail-font-code);font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--lead-line);letter-spacing:var(--body-track);tab-size:2} @.numbered .lines p{counter-increment:source-line;position:relative;padding-left:calc(var(--gap-lg)*1.2)} @.numbered .lines p::before{content:counter(source-line);position:absolute;left:0;width:var(--gap);text-align:right;color:var(--n-7)} @ .k{font-weight:var(--name-weight);color:var(--a1-7)} @ .s{color:var(--a2-7)} @ .c{color:var(--n-7)} @ .n{font-weight:var(--name-weight)} @container(max-width:650px){@ .lines p{font-size:var(--type-14)} @>.name{font-size:var(--type-16)}}''','A monospaced listing sits between a strong top rule and a quiet lower rule. A separate file label, preserved indentation, and optional counter-generated line numbers keep source readable; token colour remains subordinate to the text.')
